import * as THREE from 'three/webgpu';
import { uniform, texture } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.position.set(...config.scenePosition);
  group.rotation.set(...config.sceneRotation);
  group.scale.set(...config.sceneScale);

  // Color palette
  const colors = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    surface: new THREE.Color('#0b0b10')
  };

  // Load brushed-metal texture
  const metalTexture = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');

  // Row dimensions
  const rowWidth = 5;
  const rowHeight = 0.35;

  // === Background Plane ===
  const bgGeometry = new THREE.PlaneGeometry(rowWidth, rowHeight);
  const texNode = texture(metalTexture);
  const paperColorNode = uniform(colors.paper);

  const bgMaterial = new MeshBasicNodeMaterial({
    colorNode: texNode.mul(paperColorNode),
    side: THREE.DoubleSide,
    transparent: true
  });

  const bgMesh = new THREE.Mesh(bgGeometry, bgMaterial);
  bgMesh.position.z = 0.01;
  group.add(bgMesh);

  // === Subtle Divider Line ===
  const dividerGeometry = new THREE.PlaneGeometry(rowWidth, 0.004);
  const dividerColorNode = uniform(colors.surface);
  const dividerMaterial = new MeshBasicNodeMaterial({
    colorNode: dividerColorNode,
    side: THREE.DoubleSide,
    transparent: true
  });
  dividerMaterial.opacity = 0.4;

  const dividerMesh = new THREE.Mesh(dividerGeometry, dividerMaterial);
  dividerMesh.position.y = -(rowHeight / 2) - 0.005;
  dividerMesh.position.z = 0.02;
  group.add(dividerMesh);

  // === Accent/Focus Edge ===
  const accentGeometry = new THREE.PlaneGeometry(rowWidth, rowHeight);
  const accentColorNode = uniform(colors.accent);
  const accentMaterial = new MeshBasicNodeMaterial({
    colorNode: accentColorNode,
    side: THREE.DoubleSide,
    transparent: true
  });
  accentMaterial.opacity = 0;

  const accentMesh = new THREE.Mesh(accentGeometry, accentMaterial);
  accentMesh.position.z = 0.03;
  group.add(accentMesh);

  // State tracking
  const state = { isHovering: false };
  const originalY = config.scenePosition[1];

  // === Event Handlers ===
  group.userData.handlers = {};

  group.userData.handlers.pointerenter = () => {
    state.isHovering = true;

    // Hover lift: rise-in effect (0.15 units, power3.out, 0.7s)
    gsap.to(group.position, {
      y: group.position.y + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });

    // Show accent edge
    gsap.to(accentMaterial, {
      opacity: 0.2,
      duration: 0.5,
      ease: 'power2.out'
    });
  };

  group.userData.handlers.pointerleave = () => {
    state.isHovering = false;

    // Return to original position
    gsap.to(group.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out'
    });

    // Hide accent edge
    gsap.to(accentMaterial, {
      opacity: 0,
      duration: 0.5,
      ease: 'power2.out'
    });
  };

  group.userData.handlers.click = () => {
    // Press-down effect: scale to 0.97 then back to 1.0
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(group.scale, {
          x: 1,
          y: 1,
          duration: 0.12,
          ease: 'back.out'
        });
      }
    });

    // Emit the selection event
    if (ctx.emit) {
      ctx.emit('hub-collection.select');
    }
  };

  // === Cleanup Function ===
  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(bgMaterial);
    gsap.killTweensOf(dividerMaterial);
    gsap.killTweensOf(accentMaterial);

    bgGeometry.dispose();
    bgMaterial.dispose();
    dividerGeometry.dispose();
    dividerMaterial.dispose();
    accentGeometry.dispose();
    accentMaterial.dispose();
    metalTexture.dispose();
  };

  return group;
}
